@login_required
def attach_device_configuration(request):
    if request.method == 'POST':
        form = DeviceConfigAttachForm(request.POST)
        if form.is_valid():
            device_id = form.cleaned_data['device_id']
            profile_id = form.cleaned_data['profile_id']
            user_org = request.user.organization
            device = get_object_or_404(IoTDevice, id=device_id, organization=user_org)
            profile = get_object_or_404(ConfigProfile, id=profile_id, organization=user_org)
            device.active_profile = profile
            device.save(update_fields=['active_profile'])
            return redirect('iot_dashboard')
    else:
        form = DeviceConfigAttachForm()
    return render(request, 'iot/attach_profile.html', {'form': form})
